// Evaluates a pathway's criteria against one person's profile.
//
// The design rule that matters: an unknown is never a rejection. If a profile
// does not say whether someone has a degree, the honest answer is "check this",
// not "you do not qualify". Telling someone a door is closed when it is merely
// unverified is the most damaging error this can make.


export const PROFILE_FIELDS = new Set(["label","age","retired","annualIncomeUsd","passiveIncomeUsd","liquidSavingsUsd","investableCapitalUsd","netWorthUsd","familyTie","hasLocalJobOffer","employerIsLocalEntity","employerIsLargeEnough","intraCompanyTransfer","remoteWorkForForeignEmployer","isEmployee","hasDegree","yearsExperience","sector","enrollingInStudy","needsWorkAuthorization","needsLocalBanking","bringingFamily","wantsPermanence","maxStayMonths"]);

const OPS = {
  gte:  (a, b) => a >= b,
  lte:  (a, b) => a <= b,
  gt:   (a, b) => a > b,
  lt:   (a, b) => a < b,
  eq:   (a, b) => a === b,
  ne:   (a, b) => a !== b,
  in:   (a, b) => Array.isArray(b) && b.includes(a),
  notIn:(a, b) => Array.isArray(b) && !b.includes(a),
  isTrue:  a => a === true,
  isFalse: a => a === false,
};

const READABLE = {
  gte: 'at least', lte: 'at most', gt: 'more than', lt: 'less than',
  eq: 'exactly', ne: 'not', in: 'one of', notIn: 'not one of',
  isTrue: 'yes', isFalse: 'no',
};

/** Renders a condition as something a buyer would recognise. */
export function describe(cond) {
  const v = Array.isArray(cond.value) ? cond.value.join(' or ') : cond.value;
  if (cond.op === 'isTrue' || cond.op === 'isFalse') {
    return `${cond.field} must be ${cond.op === 'isTrue' ? 'yes' : 'no'}`;
  }
  return `${cond.field} ${READABLE[cond.op] ?? cond.op} ${v}`;
}

function evalCondition(cond, profile) {
  const actual = profile[cond.field];
  if (actual === undefined || actual === null) return { state: 'unknown', cond, actual };
  const fn = OPS[cond.op];
  if (!fn) return { state: 'unknown', cond, actual };
  return { state: fn(actual, cond.value) ? 'pass' : 'fail', cond, actual };
}

function evalAll(conds, profile) {
  const results = (conds ?? []).map(c => evalCondition(c, profile));
  return {
    failed: results.filter(r => r.state === 'fail'),
    unknown: results.filter(r => r.state === 'unknown'),
    passed: results.filter(r => r.state === 'pass'),
  };
}

/**
 * @returns { status: 'open' | 'check' | 'closed', failed, unknown, matchedGroup, blockers }
 *   open   — everything known passes
 *   check  — nothing fails, but something could not be evaluated
 *   closed — a hard requirement fails
 */
export function matchPathway(pathway, profile) {
  const c = pathway.criteria;
  if (!c) return { status: 'check', failed: [], unknown: [], blockers: [], specificity: 0,
                   note: 'no machine-evaluable criteria — read the pathway in full' };

  const base = evalAll(c.all, profile);
  if (base.failed.length) {
    return { status: 'closed', failed: base.failed, unknown: base.unknown, blockers: base.failed, note: c.note };
  }

  let matchedGroup = null, groupResult = null;
  if (c.any?.length) {
    const groups = c.any.map(g => ({ label: g.label, ...evalAll(g.all, profile) }));
    const open = groups.find(g => !g.failed.length && !g.unknown.length);
    const maybe = groups.find(g => !g.failed.length);
    if (open) { matchedGroup = open.label; groupResult = open; }
    else if (maybe) { matchedGroup = maybe.label; groupResult = maybe; }
    else {
      // Every category failed. Report the one that came closest — it is the
      // realistic target if they want to change something.
      const closest = groups.reduce((a, b) => (a.failed.length <= b.failed.length ? a : b));
      return { status: 'closed', failed: closest.failed, unknown: closest.unknown,
               blockers: closest.failed, closestGroup: closest.label, note: c.note };
    }
  }

  const unknown = [...base.unknown, ...(groupResult?.unknown ?? [])];
  // How specifically this pathway engaged with the profile. A route gated on
  // "age 55 and retired" is a better answer for a retiree than an open-to-all
  // gateway visa, even though both are equally available.
  const specificity = base.passed.length + (groupResult?.passed.length ?? 0);
  return {
    status: unknown.length ? 'check' : 'open',
    failed: [], unknown, blockers: [], matchedGroup, specificity, note: c.note,
  };
}

/** Every pathway in one pack, matched and split by status. */
export function matchPack(pack, profile) {
  const results = (pack.pathways ?? []).map(p => ({
    country: pack.meta.country,
    countryCode: pack.meta.countryCode,
    pathwayId: p.id,
    name: p.name,
    difficulty: p.difficulty,
    summary: p.summary,
    durationGranted: p.durationGranted,
    canWorkLocally: p.canWorkLocally,
    leadsToPermanentResidence: p.leadsToPermanentResidence,
    ...matchPathway(p, profile),
  }));
  return {
    country: pack.meta.country,
    countryCode: pack.meta.countryCode,
    packVersion: pack.meta.version,
    open: results.filter(r => r.status === 'open'),
    check: results.filter(r => r.status === 'check'),
    closed: results.filter(r => r.status === 'closed'),
    all: results,
  };
}
